(() => {
 'use strict';
 const $=id=>document.getElementById(id),form=$('inbox-login'),list=$('inbox-list'),feedbackList=$('feedback-list'),feedbackButton=$('feedback-refresh');
 const base=window.PeregriniReactionsConfig?.apiUrl?.trim().replace(/\/$/,'');
 let endpoint='';try{const u=new URL(base);if(u.protocol==='https:'&&!u.username&&!u.password&&u.pathname==='/'&&!u.search&&!u.hash)endpoint=u.origin;}catch{}
 let key='',generation=0,timer,next=null,loading=false,feedbackLoading=false;
 const notice=text=>{$('inbox-notice').textContent=text;};
 const feedbackNotice=text=>{$('feedback-notice').textContent=text;};
 function count(n){$('inbox-count').textContent=n?` (${n} novas)`:'';}
 function lock(clearInput=true){generation++;key='';clearInterval(timer);list.replaceChildren();feedbackList.replaceChildren();$('inbox-content').hidden=true;form.hidden=false;count(0);if(clearInput)$('inbox-key').value='';feedbackButton.disabled=true;feedbackNotice('Abra as mensagens acima para liberar o feedback.');loading=false;feedbackLoading=false;}
 async function request(path,options={}){if(!endpoint)throw Error('Preencha a URL em reactions-config.js.');const r=await fetch(endpoint+path,{...options,headers:{Authorization:'Bearer '+key,...(options.body?{'Content-Type':'application/json'}:{})},credentials:'omit',cache:'no-store',redirect:'error',signal:AbortSignal.timeout(15000)});const data=await r.json();if(!r.ok){if(r.status===401)lock(false);throw Error(data.error||'Não foi possível consultar as mensagens.');}return data;}
 async function refresh(append=false){if(loading||!key)return;loading=true;const g=generation;try{const data=await request('/admin/inbox'+(append&&next?'?before='+next:''));if(g!==generation)return;count(data.unread);if(!append)list.replaceChildren();data.items.forEach(render);next=data.next;$('inbox-more').hidden=!next;notice(list.childElementCount?'':'Nenhuma mensagem recebida.');}catch(e){notice(e.message);}finally{loading=false;}}
 function renderFeedback(item){const article=document.createElement('article');article.className='feedback-item';const title=document.createElement('h3');title.textContent=item.title||item.work;article.append(title);const format=document.createElement('small');format.textContent=(item.format||'')+' · '+item.work;article.append(format);const values=document.createElement('div');values.className='feedback-values';const likes=document.createElement('span');likes.textContent='♡ '+item.likes;likes.title='Corações públicos';const dislikes=document.createElement('span');dislikes.textContent='👎 '+item.dislikes;dislikes.title='Não gostei (visível apenas ao autor)';values.append(likes,dislikes);article.append(values);feedbackList.append(article);}
 async function refreshFeedback(){if(feedbackLoading||!key)return;feedbackLoading=true;feedbackButton.disabled=true;feedbackNotice('Carregando feedback…');try{const data=await request('/admin/feedback');feedbackList.replaceChildren();data.items.forEach(renderFeedback);feedbackNotice(data.items.length?'':'Ainda não há textos publicados para mostrar.');}catch(e){feedbackNotice(e instanceof TypeError?'Não foi possível conectar ao serviço. Abra o editor pelo endereço oficial do GitHub Pages e confirme o Worker.':e.message);}finally{feedbackLoading=false;feedbackButton.disabled=false;}}
 async function action(item,status){if(status==='delete'&&!confirm('Excluir definitivamente esta mensagem e os contatos informados?'))return;const g=generation;try{await request('/admin/message',{method:'POST',body:JSON.stringify({id:item.id,status})});if(g!==generation)return;await refresh();notice(status==='delete'?'Mensagem excluída.':'Estado atualizado.');}catch(e){notice(e.message);}}
 function render(item){const article=document.createElement('article');article.className='inbox-item';function el(tag,text){const node=document.createElement(tag);node.textContent=text;article.append(node);return node;}
  el('h3',item.kind==='email_click'?'Clique em enviar e-mail':(item.name||'Leitor')+' · Mensagem');
  el('p',item.title);const labels={new:'Nova',read:'Lida',replied:'Respondida',archived:'Arquivada'};el('small',(labels[item.status]||item.status)+' · '+new Date(item.created_at.replace(' ','T')+'Z').toLocaleString('pt-BR'));
  if(item.kind==='email_click')el('p','Um visitante clicou em enviar e-mail sobre este texto. O clique não confirma o envio nem identifica o visitante.');
  else{el('p',item.email);el('p',item.message).className='inbox-question';const reply=el('a','Responder por e-mail ↗');reply.className='inbox-reply';const title=item.title.replace(/[\r\n]/g,' ');reply.href='mailto:'+encodeURIComponent(item.email)+'?subject='+encodeURIComponent('Re: '+title)+'&body='+encodeURIComponent('Olá'+(item.name?', '+item.name:'')+'!\n\nEm resposta à sua pergunta sobre “'+title+'”:\n\n\n\n— Sua mensagem —\n'+item.message+'\n\nTexto: https://dantealeks.github.io/Ensaios-Filosoficos/obras/'+item.work+'.html');reply.addEventListener('click',()=>{if(item.status==='new')action(item,'read');});
   const copy=el('button','Copiar pergunta e contato');copy.type='button';copy.onclick=async()=>{try{await navigator.clipboard.writeText(item.email+'\n'+item.title+'\n\n'+item.message);notice('Pergunta e contato copiados.');}catch{notice('Selecione e copie o contato e a pergunta exibidos na mensagem.');}};
  }
  const controls=document.createElement('div');controls.className='inbox-actions';article.append(controls);
  for(const [status,label] of [['read','Marcar lida'],...(item.kind==='message'?[['replied','Marcar respondida']]:[]),['archived','Arquivar'],['delete','Excluir']]){const b=document.createElement('button');b.type='button';b.textContent=label;b.disabled=item.status===status;b.onclick=()=>action(item,status);controls.append(b);}
  list.append(article);
 }
 async function open(value){if(loading)return false;const button=form.querySelector('button');const label=button.textContent;button.disabled=true;button.textContent='Verificando…';const candidate=(value===undefined?$('inbox-key').value:value).trim();if(!candidate){notice('Informe a chave da caixa de mensagens para abrir esta seção.');button.disabled=false;button.textContent=label;return false;}if(candidate.length<32){notice('A chave da caixa de mensagens deve ter pelo menos 32 caracteres.');button.disabled=false;button.textContent=label;return false;}key=candidate;const g=++generation;notice('Abrindo a caixa de entrada…');try{const data=await request('/admin/inbox');if(g!==generation)return false;form.hidden=true;$('inbox-key').value='';$('inbox-content').hidden=false;feedbackButton.disabled=false;list.replaceChildren();data.items.forEach(render);next=data.next;$('inbox-more').hidden=!next;count(data.unread);notice(data.items.length?'':'Nenhuma mensagem recebida.');await refreshFeedback();clearInterval(timer);timer=setInterval(async()=>{if(document.hidden||loading||!key)return;const data=await request('/admin/inbox').catch(()=>null);if(data&&g===generation)count(data.unread);},60000);return true;}catch(e){lock(false);notice(e instanceof TypeError?'Não foi possível conectar ao serviço. Abra o editor pelo endereço oficial do GitHub Pages.':e.message);return false;}finally{button.disabled=false;button.textContent=label;}}
 form.onsubmit=async e=>{e.preventDefault();await open();};
 $('inbox-key').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();if(typeof form.requestSubmit==='function')form.requestSubmit();else form.onsubmit(e);}});
 $('inbox-refresh').onclick=()=>refresh();$('inbox-more').onclick=()=>refresh(true);$('inbox-lock').onclick=()=>{lock();notice('Caixa de entrada fechada.');};feedbackButton.onclick=()=>refreshFeedback();
 $('inbox-diagnose').onclick=async()=>{if(!endpoint){notice('A URL do serviço não está configurada.');return;}notice('Verificando conexão…');try{const r=await fetch(endpoint+'/health',{cache:'no-store',credentials:'omit',signal:AbortSignal.timeout(15000)}),data=await r.json();if(!Array.isArray(data.missing))throw Error();const names={DB:'vínculo D1 chamado DB',REACTION_SALT:'segredo REACTION_SALT (mínimo 32 caracteres)',MESSAGES_ADMIN_KEY:'segredo MESSAGES_ADMIN_KEY (mínimo 32 caracteres)','table:reactions':'tabela reactions','table:rate_limits':'tabela rate_limits','table:private_messages':'tabela private_messages'};notice(data.ready?'Conexão pronta. Avaliações e caixa de entrada configuradas.':'Falta configurar na Cloudflare: '+data.missing.map(x=>names[x]||x).join('; ')+'.');}catch{notice('Não foi possível verificar. Confirme se o novo Worker foi publicado na Cloudflare.');}};
 window.PeregriniInbox={open,lock};
 window.addEventListener('pagehide',lock);
})();
